def applied_entries(seq):
    for e in seq or []:
        if isinstance(e, dict) and e.get("applied", False):
            yield e

# For a .pdf target in Word, actual PDF text is only determined by a real conversion.
# If conversion_source is provided, it contains the copied logical input at conversion time.
snapshot = data.get("conversion_source")
if isinstance(snapshot, dict):
    state = snapshot.get("state", {})
    if isinstance(state, dict):
        content = state.get("content", "")
    else:
        content = ""
else:
    # Without a conversion snapshot, a Word file named .pdf is still a DOCX container,
    # and no pure-computation PDF text can be derived from later writes alone.
    content = ""

print_json({"text": content})

